<?php $editable=!$submission || in_array($submission['status'],['draft','revision_requested'],true); ?>
<a class="text-link small muted" href="<?= e(route_url('/paths/' . ($assignment['path_slug']))) ?>" style="margin-bottom:22px"><?= icon('arrow-left',15) ?> Back to my learning map</a>
<div class="two-column"><div class="stack"><section class="card assignment-intro"><span class="eyebrow orange-text">A LITTLE LEARNING, PUT TO WORK</span><h1><?= e($assignment['title']) ?></h1><p style="font-size:13px;color:var(--muted);line-height:1.9;margin-bottom:22px"><?= e($assignment['description']) ?></p><div class="page-actions" style="margin-bottom:24px"><?= badge($submission['status']??'not_started') ?><span class="badge badge-neutral"><?= $assignment['required']?'Required assignment':'Optional practice' ?></span></div><div class="prose"><?= lessonHtml($assignment['instructions']) ?></div><?php if($assignment['objectives']): ?><h3 style="font-size:15px;margin:25px 0 18px">What you’re practising</h3><ul class="objective-list"><?php foreach(lines($assignment['objectives']) as $item): ?><li><?= icon('check-circle',15) ?><span><?= e($item) ?></span></li><?php endforeach; ?></ul><?php endif; ?></section>
<section class="card form-card"><h2 class="form-section-title"><?= $editable?($submission && $submission['status']==='revision_requested'?'A thoughtful revision.':'Show what you can do.'):'Your submitted work.' ?></h2><p class="form-section-description"><?= $editable?'Save a draft while you’re working, or submit when you’re ready for feedback.':'This version is locked. You can revise it if your reviewer requests changes.' ?></p>
<?php if($editable): ?><form action="<?= e(route_url('/api/assignments/' . ((int)$assignment['id']))) ?>" method="post" enctype="multipart/form-data" data-api><?= csrfField() ?><?php if($assignment['allow_text']): ?><div class="field"><label for="submission-content">Your response and explanation</label><textarea id="submission-content" name="content" maxlength="15000" placeholder="Explain what you built, what you learned, and anything you’d like feedback on…" style="min-height:200px"><?= e($submission['content']??'') ?></textarea></div><?php endif; ?><?php if($assignment['allow_url']): ?><div class="field"><label for="project-url">Project or repository URL</label><input id="project-url" name="project_url" type="url" value="<?= e($submission['project_url']??'') ?>" placeholder="https://…" maxlength="2000"><span class="field-help">Make sure your reviewer can access this link. Don’t share passwords or private keys.</span></div><?php endif; ?><?php if($assignment['allow_file']): ?><div class="upload-zone"><?= icon('upload',26) ?><p>Something useful to show?</p><small>PDF, TXT, JPG or PNG · maximum 5 MB</small><input type="file" name="attachment" accept=".pdf,.txt,.jpg,.jpeg,.png" aria-label="Assignment attachment"></div><?php if(!empty($submission['file_key'])): ?><p class="fine-print" style="margin-top:10px">Current attachment: <a href="<?= e(route_url('/downloads/submissions/' . ((int)$submission['id']))) ?>"><?= e($submission['file_name']) ?></a>. A new upload replaces the current attachment.</p><?php endif; endif; ?><div class="form-actions"><button type="submit" class="btn btn-secondary" name="action" value="draft">Save a draft</button><button type="submit" class="btn btn-primary" name="action" value="submitted" data-confirm="Ready for a fresh perspective? Your work will be locked until a reviewer provides feedback or requests a revision.">Submit for review <?= icon('arrow-right',16) ?></button></div></form>
<?php else: ?><div class="review-response"><?= e($submission['content']?:'No text response was submitted.') ?></div><div class="page-actions"><?php if($submission['project_url']): ?><a href="<?= e($submission['project_url']) ?>" class="btn btn-secondary btn-small" target="_blank" rel="noopener noreferrer">View submitted project <?= icon('arrow-up-right',14) ?></a><?php endif; ?><?php if($submission['file_key']): ?><a class="btn btn-secondary btn-small" href="<?= e(route_url('/downloads/submissions/' . ((int)$submission['id']))) ?>"><?= icon('download',14) ?> <?= e($submission['file_name']) ?></a><?php endif; ?></div><?php endif; ?></section></div>
<aside class="stack"><section class="card card-pad"><div class="card-header"><h2>What good looks like.</h2><?= icon('target',19) ?></div><p class="fine-print" style="margin-bottom:14px">Your reviewer uses these published criteria.</p><?php foreach($rubrics as $r): ?><div class="key-value"><span><?= e($r['criterion']) ?></span><strong><?= (int)$r['max_points'] ?> pts</strong></div><?php endforeach; ?><div class="key-value"><span>Maximum score</span><strong><?= (int)$assignment['max_score'] ?></strong></div><div class="key-value"><span>Required for acceptance</span><strong><?= (int)$assignment['passing_score'] ?></strong></div><div class="key-value"><span>Due</span><strong><?= $assignment['due_at']?niceDate($assignment['due_at'],'M j, Y · H:i').' UTC':'At your own pace' ?></strong></div><?php if($submission && $submission['score']!==null): ?><div class="key-value"><span>Your reviewed score</span><strong><?= e($submission['score']) ?> / <?= (int)$assignment['max_score'] ?></strong></div><?php endif; ?></section><section class="card card-pad"><div class="card-header"><h2>A fresh perspective.</h2><?= icon('message',18) ?></div><?php if($feedback): ?><?php foreach($feedback as $f): ?><article class="feedback-card"><h4><span><?= e($f['full_name']) ?></span><?= badge($f['action']) ?></h4><p><?= e($f['feedback']) ?></p><small><?= niceDate($f['created_at'],'M j, Y · H:i') ?> UTC<?= $f['score']!==null?' · Score '.e($f['score']):'' ?></small></article><?php endforeach; ?><?php else: ?><div class="mini-empty"><?= icon('message',25) ?><p>Your reviewer’s feedback will appear here. Good work grows with a little perspective.</p></div><?php endif; ?></section><?php if($history): ?><section class="card card-pad"><div class="card-header"><h2>Your work, along the way.</h2></div><div class="submission-history"><?php foreach($history as $h): ?><div class="history-item"><span></span><div><?= badge($h['status']) ?><p style="margin-top:5px"><?= niceDate($h['created_at'],'M j, Y · H:i') ?> UTC</p></div></div><?php endforeach; ?></div></section><?php endif; ?></aside></div>
